content:
:root {
  font-family: Inter, system-ui, Avenir, Helvetica, Arial, sans-serif;
  line-height: 1.5;
  font-weight: 400;

  color-scheme: light dark;
  --text-main: #1a1a1a;
  --text-muted: #475569;
  --bg-app: #ffffff;
  --bg-body: #f0f2f5;
  --bg-control: #f8fafc;
  --border-color: #cbd5e1;

  color: var(--text-main);
  background-color: var(--bg-body);

  font-synthesis: none;
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  margin: 0;
  display: flex;
  place-items: center;
  justify-content: center;
  min-width: 320px;
  min-height: 100vh;
}

.app-container {
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 2rem;
  background: var(--bg-app);
  border-radius: 16px;
  box-shadow: 0 10px 25px rgba(0, 0, 0, 0.1);
  max-width: 700px;
  width: 100%;
  box-sizing: border-box;
}

.piano-title {
  font-size: 1.8rem;
  font-weight: 700;
  margin-bottom: 1.5rem;
  color: var(--text-main);
  text-align: center;
}

.control-panel {
  display: flex;
  flex-wrap: wrap;
  gap: 1.5rem;
  justify-content: center;
  align-items: center;
  margin-bottom: 2rem;
  width: 100%;
  background: var(--bg-control);
  padding: 1rem;
  border-radius: 8px;
  box-sizing: border-box;
}

.control-group {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 0.5rem;
}

.settings-label {
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--text-muted);
}

.btn {
  padding: 0.5rem 1rem;
  font-size: 0.9rem;
  font-weight: 500;
  border: 1px solid var(--border-color);
  border-radius: 6px;
  background-color: var(--bg-app);
  color: #334155;
  cursor: pointer;
  transition: all 0.2s ease;
}

.btn:hover {
  background-color: #f1f5f9;
  border-color: #94a3b8;
}

.btn:active {
  background-color: #e2e8f0;
}

.piano-box {
  display: flex;
  justify-content: center;
  width: 100%;
  overflow-x: auto;
  padding: 1rem 0;
}

.keyboard {
  position: relative;
  display: flex;
  background-color: #1e293b;
  padding: 10px;
  border-radius: 8px;
  box-shadow: 0 8px 20px rgba(0, 0, 0, 0.2);
  user-select: none;
  touch-action: none;
}

.white-key {
  position: relative;
  width: 50px;
  height: 180px;
  background: linear-gradient(to bottom, #ffffff 0%, #e2e8f0 100%);
  border: 1px solid var(--border-color);
  border-radius: 0 0 6px 6px;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  align-items: center;
  padding-bottom: 10px;
  cursor: pointer;
  box-sizing: border-box;
  transition: background 0.1s ease;
  z-index: 1;
}

.white-key:hover {
  background: linear-gradient(to bottom, #f8fafc 0%, #cbd5e1 100%);
}

.white-key.active {
  background: linear-gradient(to bottom, #cbd5e1 0%, #94a3b8 100%) !important;
  box-shadow: inset 0 4px 6px rgba(0, 0, 0, 0.2);
}

.black-key {
  position: absolute;
  width: 32px;
  height: 110px;
  background: linear-gradient(to bottom, #334155 0%, #0f172a 100%);
  border-radius: 0 0 4px 4px;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  align-items: center;
  padding-bottom: 8px;
  cursor: pointer;
  box-sizing: border-box;
  z-index: 2;
  transition: background 0.1s ease;
  color: #ffffff;
}

.black-key:hover {
  background: linear-gradient(to bottom, #475569 0%, #1e293b 100%);
}

.black-key.active {
  background: linear-gradient(to bottom, #0f172a 0%, #000000 100%) !important;
  box-shadow: inset 0 3px 5px rgba(0, 0, 0, 0.5);
}

@media (max-width: 600px) {
  .app-container {
    padding: 1rem;
  }

  .white-key {
    width: 38px;
    height: 140px;
  }

  .black-key {
    width: 24px;
    height: 85px;
  }

  /* レスポンシブ時の黒鍵の位置調整（インラインのleftを比率に合わせて上書き） */
  .keyboard > :nth-child(2) { left: 27px !important; }
  .keyboard > :nth-child(4) { left: 65px !important; }
  .keyboard > :nth-child(7) { left: 141px !important; }
  .keyboard > :nth-child(9) { left: 179px !important; }
  .keyboard > :nth-child(11) { left: 217px !important; }
}

export interface NoteKey {
  note: string;
  freq: number;
  type: 'white' | 'black';
  label: string;
  computerKey: string;
  octave?: number;
  midiNote?: number;
}

export interface PianoSettings {
  volume: number;
  waveType: OscillatorType;
}

import { PianoSettings } from '../types';

let audioCtx: AudioContext | null = null;
let masterGainNode: GainNode | null = null;

const getAudioContext = () => {
  if (!audioCtx) {
    const AudioContextClass = window.AudioContext || (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext;
    audioCtx = new AudioContextClass();
    masterGainNode = audioCtx.createGain();
    // 複数音の同時発音時の音割れ（クリッピング）を防ぐためのマスターボリューム調整
    masterGainNode.gain.setValueAtTime(0.6, audioCtx.currentTime);
    masterGainNode.connect(audioCtx.destination);
  }

  if (audioCtx.state === 'suspended') {
    audioCtx.resume();
  }

  return { audioCtx, masterGainNode };
};

export const playTone = (freq: number, waveType: OscillatorType, volume: number) => {
  try {
    const { audioCtx, masterGainNode } = getAudioContext();
    if (!audioCtx || !masterGainNode) return;

    const osc = audioCtx.createOscillator();
    const gainNode = audioCtx.createGain();

    osc.type = waveType;
    osc.frequency.setValueAtTime(freq, audioCtx.currentTime);

    const now = audioCtx.currentTime;
    const targetVolume = Math.max(0, Math.min(1, volume));

    // 立ち上がり・減衰のエンベロープでノイズを防止
    gainNode.gain.setValueAtTime(0, now);
    gainNode.gain.linearRampToValueAtTime(targetVolume, now + 0.03);
    gainNode.gain.exponentialRampToValueAtTime(0.0001, now + 1.2);

    osc.connect(gainNode);
    gainNode.connect(masterGainNode);

    osc.start(now);
    osc.stop(now + 1.2);

    // 再生終了後のクリーンアップ処理
    osc.onended = () => {
      osc.disconnect();
      gainNode.disconnect();
    };
  } catch (e) {
    console.error('Web Audio API error:', e);
  }
};

import { useState, useEffect, useCallback } from 'react';
import { NoteKey, PianoSettings } from '../types';
import { playTone } from '../utils/audio';

interface PianoProps {
  settings: PianoSettings;
}

const KEYS: NoteKey[] = [
  { note: 'C4', freq: 261.63, type: 'white', label: 'C', computerKey: 'a' },
  { note: 'Cs4', freq: 277.18, type: 'black', label: 'C#', computerKey: 'w' },
  { note: 'D4', freq: 293.66, type: 'white', label: 'D', computerKey: 's' },
  { note: 'Ds4', freq: 311.13, type: 'black', label: 'D#', computerKey: 'e' },
  { note: 'E4', freq: 329.63, type: 'white', label: 'E', computerKey: 'd' },
  { note: 'F4', freq: 349.23, type: 'white', label: 'F', computerKey: 'f' },
  { note: 'Fs4', freq: 369.99, type: 'black', label: 'F#', computerKey: 't' },
  { note: 'G4', freq: 392.00, type: 'white', label: 'G', computerKey: 'g' },
  { note: 'Gs4', freq: 415.30, type: 'black', label: 'G#', computerKey: 'y' },
  { note: 'A4', freq: 440.00, type: 'white', label: 'A', computerKey: 'h' },
  { note: 'As4', freq: 466.16, type: 'black', label: 'A#', computerKey: 'u' },
  { note: 'B4', freq: 493.88, type: 'white', label: 'B', computerKey: 'j' },
  { note: 'C5', freq: 523.25, type: 'white', label: 'C5', computerKey: 'k' },
];

export default function Piano({ settings }: PianoProps) {
  const [activeNotes, setActiveNotes] = useState<Record<string, boolean>>({});

  const triggerNote = useCallback((key: NoteKey) => {
    playTone(key.freq, settings.waveType, settings.volume);
    setActiveNotes((prev) => ({ ...prev, [key.note]: true }));
    setTimeout(() => {
      setActiveNotes((prev) => ({ ...prev, [key.note]: false }));
    }, 200);
  }, [settings]);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.repeat) return;
      const found = KEYS.find((k) => k.computerKey === e.key.toLowerCase());
      if (found) {
        playTone(found.freq, settings.waveType, settings.volume);
        setActiveNotes((prev) => ({ ...prev, [found.note]: true }));
      }
    };

    const handleKeyUp = (e: KeyboardEvent) => {
      const found = KEYS.find((k) => k.computerKey === e.key.toLowerCase());
      if (found) {
        setActiveNotes((prev) => ({ ...prev, [found.note]: false }));
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
    };
  }, [settings]);

  // 黒鍵のレイアウト計算（白鍵の個数に基づく動的計算）
  const getBlackKeyLeft = (index: number) => {
    const whiteCountBefore = KEYS.slice(0, index).filter((k) => k.type === 'white').length;
    // 白鍵幅50pxを基準に、黒鍵幅32pxの中央配置を算出
    return whiteCountBefore * 50 - 16;
  };

  return (
    <div className="piano-box">
      <div className="keyboard">
        {KEYS.map((key, index) => {
          const isActive = !!activeNotes[key.note];
          if (key.type === 'white') {
            return (
              <div
                key={key.note}
                className={`white-key ${isActive ? 'active' : ''}`}
                onMouseDown={() => triggerNote(key)}
                onTouchStart={(e) => {
                  e.preventDefault();
                  triggerNote(key);
                }}
              >
                <span style={{ fontSize: '0.75rem', color: '#94a3b8' }}>{key.label}</span>
                <span style={{ fontSize: '0.65rem', color: '#cbd5e1' }}>({key.computerKey.toUpperCase()})</span>
              </div>
            );
          } else {
            const leftPos = getBlackKeyLeft(index);
            return (
              <div
                key={key.note}
                className={`black-key ${isActive ? 'active' : ''}`}
                style={{ left: `${leftPos}px` }}
                onMouseDown={(e) => {
                  e.stopPropagation();
                  triggerNote(key);
                }}
                onTouchStart={(e) => {
                  e.stopPropagation();
                  e.preventDefault();
                  triggerNote(key);
                }}
              >
                <span style={{ fontSize: '0.6rem', color: '#94a3b8' }}>{key.computerKey.toUpperCase()}</span>
              </div>
            );
          }
        })}
      </div>
    </div>
  );
}

import { useState, useEffect } from 'react';
import Piano from './components/Piano';
import { PianoSettings } from './types';

const STORAGE_KEY = 'web_piano_settings_v1';

export default function App() {
  const [settings, setSettings] = useState<PianoSettings>(() => {
    try {
      const saved = localStorage.getItem(STORAGE_KEY);
      if (saved) {
        const parsed = JSON.parse(saved);
        return {
          volume: typeof parsed.volume === 'number' ? parsed.volume : 0.5,
          waveType: ['sine', 'square', 'sawtooth', 'triangle'].includes(parsed.waveType) ? parsed.waveType : 'sine',
        };
      }
    } catch (e) {
      console.error('Failed to load settings from localStorage', e);
    }
    return {
      volume: 0.5,
      waveType: 'sine',
    };
  });

  useEffect(() => {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(settings));
    } catch (e) {
      console.error('Failed to save settings to localStorage', e);
    }
  }, [settings]);

  const handleVolumeChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setSettings((prev) => ({ ...prev, volume: parseFloat(e.target.value) }));
  };

  const handleWaveChange = (waveType: OscillatorType) => {
    setSettings((prev) => ({ ...prev, waveType }));
  };

  const applyPreset = (preset: PianoSettings) => {
    setSettings(preset);
  };

  const waveTypes: { label: string; value: OscillatorType }[] = [
    { label: 'サイン波', value: 'sine' },
    { label: '矩形波', value: 'square' },
    { label: 'ノコギリ波', value: 'sawtooth' },
    { label: '三角波', value: 'triangle' },
  ];

  return (
    <div className="app-container">
      <h1 className="piano-title">Web ピアノアプリ</h1>

      <div className="control-panel">
        <div className="control-group">
          <span className="settings-label">音量: {Math.round(settings.volume * 100)}%</span>
          <input
            type="range"
            min="0"
            max="1"
            step="0.01"
            value={settings.volume}
            onChange={handleVolumeChange}
            style={{ cursor: 'pointer' }}
          />
        </div>

        <div className="control-group">
          <span className="settings-label">音色</span>
          <div style={{ display: 'flex', gap: '0.55rem', flexWrap: 'wrap' }}>
            {waveTypes.map((wt) => (
              <button
                key={wt.value}
                className="btn"
                style={{
                  backgroundColor: settings.waveType === wt.value ? '#e2e8f0' : '#ffffff',
                  borderColor: settings.waveType === wt.value ? '#64748b' : '#cbd5e1',
                  fontWeight: settings.waveType === wt.value ? 600 : 500,
                }}
                onClick={() => handleWaveChange(wt.value)}
              >
                {wt.label}
              </button>
            ))}
          </div>
        </div>

        <div className="control-group">
          <span className="settings-label">プリセット</span>
          <div style={{ display: 'flex', gap: '0.55rem' }}>
            <button className="btn" onClick={() => applyPreset({ volume: 0.3, waveType: 'sine' })}>
              ソフト
            </button>
            <button className="btn" onClick={() => applyPreset({ volume: 0.7, waveType: 'square' })}>
              リッチ
            </button>
          </div>
        </div>
      </div>

      <Piano settings={settings} />

      <div style={{ marginTop: '1.5rem', fontSize: '0.85rem', color: '#64748b', textAlign: 'center' }}>
        鍵盤をクリックするか、パソコンのキーボード（A, W, S, E, D, F, T, G, Y, H, U, J, K）で演奏できます。
      </div>
    </div>
  );
}
